"""Archive source stop/reload proof and exact primary/reviewer local workflow."""
import hashlib,json,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads(p.read_text())
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    cp=read(ROOT/'verification/startup-loading-movie-world-checkpoint.json');commands=read(ROOT/'verification/music-command-cycles-checks.json');regression=read(ROOT/'verification/music-command-engine-regression-checks.json')
    assert commands['stop_reload_cycles']==8 and commands['user_and_supervisor_CPU_calls_verified']and not commands['processor_reset_between_stop_and_reload']and not commands['DSP_completion_script']
    assert cp['source_music_stop_reload_separate_from_connected_game']and regression['regression_selected_instruction_coverage']==[209,209]and regression['source_instruction_coverage']==[209,316]
    primary=Path(read(ROOT/'verification/easy-music-command-scope-pointer.json')['directory']);reviewer=Path(read(ROOT/'verification/local-music-command-reviewer-pointer.json')['directory']);a=read(primary/'protocol.json');b=read(reviewer/'protocol.json');item=a['results'][0]
    assert a['status']==b['status']=='completed_pending_coordinator_review'and not item['quality_flags']and not b['quality_flags']
    assert all(s['stats']['stopReason']=='eosFound'for s in item['prediction_stats']+b['prediction_stats'])
    assert 'Yes, stopping music'in item['answer']and all(t in b['response']for t in ['No, stopping music does not halt','physical serial word clock','without processor resets'])
    corrected=b['response'].split('Corrected answer:',1)[1].strip();assert len(corrected.split())<120 and b['words']<180
    now=datetime.now(timezone.utc);out=ROOT/'verification/music-command-local-review'/now.strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
    files=[primary/'protocol.json',primary/'prompts-and-responses.txt',reviewer/'protocol.json',reviewer/'prompts-and-responses.txt',ROOT/'verification/startup-loading-movie-world-checkpoint.json',ROOT/'verification/music-command-cycles-checks.json',ROOT/'verification/music-command-engine-regression-checks.json',ROOT/'verification/music-command-MCP-check.json',ROOT/'scripts/check_biwn_music_commands.py',ROOT/'scripts/generate_biwn_music_stop_cpu.py',ROOT/'scripts/generate_biwn_music_DSP_engine.py',ROOT/'scripts/check_biwn_music_command_engine_regression.py',ROOT/'scripts/test_music_command_scope.py',ROOT/'scripts/review_music_command_local_answer.py',ROOT/'chat_tools.py',Path(__file__)]
    manifest=[]
    for i,p in enumerate(files):
        dest=out/f'{i:02d}-{p.name}';shutil.copy2(p,dest);assert sha(p)==sha(dest);manifest.append(dict(source=str(p),snapshot=str(dest),sha256=sha(p)))
    report=dict(status='source_stop_reload_verified_primary_halt_wording_rejected_local_reviewer_repair_accepted',directory=str(out),recorded_at=now.isoformat(),source_audit=cp['audit'],source_commands_directory=commands['directory'],source_regression_directory=regression['directory'],roles=[dict(role=item['role'],seconds=item['seconds'],words=item['words'],review='Correct counts/reload/standalone scope/limits; misleading leading yes to DSP halt and imprecise SSI halt wording.'),dict(role=b['role'],seconds=b['seconds'],words=b['words'],review='Correctly identifies processor not halted, GO retained/running command wait, interrupts disabled versus physical serial clock; corrected core answer accepted. Corrected answer is focused, not a full repeat of all count/scope details.')],same_weights=True,sequential_one_worker=True,independent_code_verification=False,native_Chat_verified=False,new_training=False,model_defaults_changed=False,full_music_playback_verified=False,whole_goal_complete=False,source_authorship='Coordinator authors source translations and original-processor comparisons. Local roles explain/review evidence, not code authorship.',manifest=manifest)
    save(out/'review.json',report);save(ROOT/'verification/music-command-local-review.json',report)
    transcript='COORDINATOR\n'+report['source_authorship']+'\n316source DSP blocks:209mixer/synthetic blocks checked atomically,107command/bootstrap blocks checked through source CPU command traces/full endpoint state.7source CPU stop/poll instructions verified.8stop/reload cycles/fouruser-supervisor/device profiles; separate supplied CPU entry frames, not connected game input. No processor reset/mailbox completion script.\n\nPRIMARY EXACT PROMPTS / TOOL MESSAGES / RESPONSE\n'+(primary/'prompts-and-responses.txt').read_text()+'\n\nLOCAL REVIEWER EXACT PROMPTS / TOOL MESSAGES / RESPONSE\n'+(reviewer/'prompts-and-responses.txt').read_text();(out/'who-prompts-and-responses.txt').write_text(transcript)
    note='LATEST — SOURCE MUSIC STOP / RELOAD\n'+now.isoformat()+'\n\nSourceE9EC command1 does not halt the DSP processor:GO stays1 atF1B144 command-wait loop; musicSSI/timer interrupts disabled and timer registers cleared. SourceE96C command2 loader copies/reinitializes/acknowledges and resumes mixer.8cycles/4user-supervisor/device profiles compare fullCPU/privateRAM/logicalGPU-DSP/peripherals/command traces and saved state; no processor resets/mailbox completion script. CPU entry/private frames supplied; these command calls are separate from connected game input. Expanded316DSP blocks retain209block atomic silence/synthetic regression; movie187/125 and12world cycles stillmatch2fresh profiles. Audible disc music/allvoices/commands/resources/globaltime/firmware/scanout/playability/nativeChat remain unverified.\n\n'+f'Local primary{item["seconds"]:.2f}s/{item["words"]}words had misleading leadingyes/SSIhalt wording. Same-weight reviewer{b["seconds"]:.2f}s/{b["words"]}words corrected processor halt versus interrupt disable/physicalclock distinction after evidence wording was made explicit. Source correctness comes from original-code tests; no newtraining/defaultchanges.\n\nCORRECTED CORE ANSWER\n'+corrected+'\n\nWHO / EXACT PROMPTS / RESPONSES\n'+str(out/'who-prompts-and-responses.txt')+'\n\nREVIEW\n'+str(out/'review.json')+'\n\nSOURCE AUDIT\n'+cp['audit']+'\n\n'
    for name in ['START HERE.txt','CURRENT LOCAL INFERENCE.txt']:
        p=ROOT/name;p.write_text(note+p.read_text())
    (out/'readable-results.txt').write_text(note)
    p=ROOT/'verification/NEXT SOURCE AND INFERENCE WORK.json';n=read(p);n.update(last_turn_classification='progress',source_audit=cp['audit'],local_audit=str(out))
    n['next_source_work']=[t.replace('CPU commands including music stop/reload,','remaining CPU commands and actual game stop/reload call sites (sourceE9EC/E96C now separately verified),')for t in n['next_source_work']];save(p,n)
    print(json.dumps(dict(status=report['status'],directory=str(out),primary_seconds=item['seconds'],reviewer_seconds=b['seconds'])))
if __name__=='__main__':main()
